// Package corpus embeds the canonical rigorix contract corpus (`schemas/**`) so
// the Go verifier and client are self-contained. The map is generated by
// scripts/gen-corpus; run `go generate ./...` after any `schemas/` change.
package corpus

import "sort"

//go:generate go run ../../scripts/gen-corpus

// Schema returns the contract at rel (relative to `schemas/`).
func Schema(rel string) (string, bool) {
	s, ok := files[rel]
	return s, ok
}

// Fixture returns the fixture at rel (relative to `schemas/fixtures/`).
func Fixture(rel string) (string, bool) {
	s, ok := files["fixtures/"+rel]
	return s, ok
}

// Files returns every embedded path relative to `schemas/`, sorted.
func Files() []string {
	out := make([]string, 0, len(files))
	for k := range files {
		out = append(out, k)
	}
	sort.Strings(out)
	return out
}
